const StSwatch = ({ m, w = 40, h = 48, r = 9, style }) => { const c = m.col; const tex = m.tex === 'velvet' ? `linear-gradient(160deg, rgba(255,255,255,.22), rgba(0,0,0,.25) 60%), ${c}` : m.tex === 'sequin' ? `radial-gradient(circle at 30% 30%, rgba(255,255,255,.7) 0 1.2px, transparent 1.5px) 0 0/6px 6px, radial-gradient(circle at 70% 70%, rgba(255,255,255,.35) 0 1px, transparent 1.4px) 3px 3px/6px 6px, ${c}` : m.tex === 'net' ? `repeating-linear-gradient(45deg, rgba(0,0,0,.14) 0 1px, transparent 1px 4px), repeating-linear-gradient(-45deg, rgba(0,0,0,.14) 0 1px, transparent 1px 4px), ${c}` : m.tex === 'lace' ? `radial-gradient(circle, rgba(255,255,255,.45) 0 1.5px, transparent 2px) 0 0/8px 8px, ${c}` : m.tex === 'tissue' ? `repeating-linear-gradient(0deg, rgba(255,255,255,.35) 0 1px, transparent 1px 3px), ${c}` : m.tex === 'satin' ? `linear-gradient(120deg, rgba(255,255,255,.45), transparent 40%, rgba(0,0,0,.18)), ${c}` : `linear-gradient(180deg, rgba(255,255,255,.12), rgba(0,0,0,.1)), ${c}`; return <span style={{ width: w, height: h, borderRadius: r, flex: 'none', display: 'block', background: tex, boxShadow: 'inset 0 0 0 1px rgba(0,0,0,.12)', ...style }} />; };
/* photo tile with tick + ring selection (the phone gallery idiom); foot line optional; `n` badge for grid cells */
function StTile({ T, src, pos, on, w, h, r = 12, n, foot, meta, mark, dark, style, children }) {
  return <div className="press" style={{ position: 'relative', width: w, height: h || Math.round(w * 1.2), borderRadius: r, overflow: 'hidden', background: dark ? SP.bg2 : T.photoBg, flex: 'none', ...style }}>
    {src ? stImg(src, pos) : <span style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', fontFamily: T.fontUI, fontSize: 11, color: dark ? SP.ink3 : T.ink3 }}>No photo yet</span>}
    {(foot || meta) && <div style={{ position: 'absolute', left: 0, right: 0, bottom: 0, height: '42%', background: 'linear-gradient(180deg, rgba(20,18,17,0), rgba(20,18,17,.6))', pointerEvents: 'none' }} />}
    {n != null && <span style={{ position: 'absolute', top: 6, left: 6, minWidth: 20, height: 20, padding: '0 6px', borderRadius: 10, ...veil({ background: 'rgba(8,8,12,.5)' }), fontFamily: T.fontUI, fontSize: 10.5, fontWeight: 600, display: 'grid', placeItems: 'center' }}>{n}</span>}
    {on && <><span style={{ position: 'absolute', inset: 0, boxShadow: `inset 0 0 0 2.5px ${T.accent}`, borderRadius: 'inherit', pointerEvents: 'none' }} /><span style={{ position: 'absolute', top: 6, right: 6, width: 20, height: 20, borderRadius: 10, background: T.accent, color: T.onAccent, display: 'grid', placeItems: 'center', boxShadow: '0 1px 4px rgba(0,0,0,.35), 0 0 0 1.5px rgba(255,255,255,.85)' }}><Ic name="check" size={12} sw={2.6} /></span></>}
    {mark && <span style={{ position: 'absolute', right: 6, [meta || foot ? 'top' : 'bottom']: 6 }}><StMark /></span>}
    {(foot || meta) && <div style={{ position: 'absolute', left: 8, right: 8, bottom: 6, display: 'flex', alignItems: 'baseline', gap: 6, color: '#fff', textShadow: '0 1px 2px rgba(0,0,0,.5)', whiteSpace: 'nowrap', overflow: 'hidden' }}>{foot && <span style={{ fontFamily: T.fontDisplay, fontSize: 14, fontWeight: 600, letterSpacing: '.01em' }}>{foot}</span>}<span style={{ flex: 1 }} />{meta && <span style={{ fontFamily: T.fontUI, fontSize: 10.5, opacity: .92 }}>{meta}</span>}</div>}
    {children}
  </div>;
}
const StThumb = ({ T, src, pos, w = 44, h, r = 8, ring, x, label, dark }) => <span style={{ position: 'relative', width: w, height: h || Math.round(w * 1.2), borderRadius: r, overflow: 'hidden', background: dark ? SP.bg2 : T.photoBg, flex: 'none', display: 'block', boxShadow: ring ? `0 0 0 2px ${ring}` : 'none' }}>{src ? stImg(src, pos) : <span style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center', fontFamily: T.fontUI, fontSize: 8.5, color: T.ink3 }}>none</span>}{x && <span className="press" style={{ position: 'absolute', top: 2, right: 2, width: 15, height: 15, borderRadius: 8, background: 'rgba(8,8,12,.65)', color: '#fff', display: 'grid', placeItems: 'center' }}><Ic name="x" size={9} sw={2.4} /></span>}{label && <span style={{ position: 'absolute', left: 4, bottom: 3, fontFamily: T.fontUI, fontSize: 9, fontWeight: 600, color: '#fff', textShadow: '0 1px 2px rgba(0,0,0,.6)' }}>{label}</span>}</span>;
